# Let's analyze character-by-character
inputs = ['jjggy', 'ycgxae', 'yhdwg', 'yev', 'ykzewx']
outputs = ['jjjyejyey', 'ycjyexajwj', 'yhdwjye', 'yjwjv', 'ykzcdx']

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input {i+1}: '{inp}'")
    print(f"Output {i+1}: '{out}'")
    print("Position by position analysis:")

    # Pad to same length for easier comparison
    max_len = max(len(inp), len(out))
    padded_inp = inp.ljust(max_len)
    padded_out = out.ljust(max_len)

    for j in range(max_len):
        if j < len(inp) and j < len(out):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        else:
            print(f"  Position {j}: '' -> '{out[j]}' (added)")
    print()

